import UserPage from 'flarum/forum/components/UserPage';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import BadgeCard from './BadgeCard';
import { badgesEnabled, distinctBadges, loadUserBadges, trustLevel, trustLevelName, trustLevelsEnabled } from '../utils';
import { t } from '../../../utils/settings';

/**
 * A aba "Emblemas" do perfil (/u/:username/badges): cada emblema uma vez,
 * com quantas vezes foi ganho e quando, na ordem ouro → prata → bronze.
 */
export default class UserBadgesPage extends UserPage {
  userBadges = null;

  /** O usuário cujos emblemas já foram pedidos: `show()` roda de novo quando o perfil completo chega. */
  loadedFor = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    if (this.loadedFor === user || !badgesEnabled()) return;
    this.loadedFor = user;
    loadUserBadges(user, {
      refresh: true
    }).then(userBadges => {
      this.userBadges = userBadges;
      m.redraw();
    });
  }
  content() {
    if (!badgesEnabled()) return m("p", {
      className: "CanelaBadges-empty"
    }, t('badges.unavailable'));
    const user = this.user;
    const level = trustLevel(user);
    return m("div", {
      className: "CanelaUserBadges"
    }, trustLevelsEnabled() && level !== null && m("p", {
      className: "CanelaUserBadges-level"
    }, t('badges.trust_level_label', {
      level: trustLevelName(level)
    })), this.list(user));
  }
  list(user) {
    if (this.userBadges === null) return m(LoadingIndicator, {
      display: "block"
    });
    const badges = distinctBadges(this.userBadges);
    if (!badges.length) return m("p", {
      className: "CanelaBadges-empty"
    }, t('badges.user_none', {
      username: user.displayName()
    }));
    return m("ul", {
      className: "CanelaBadges-grid"
    }, badges.map(({
      badge,
      count,
      latest
    }) => m("li", {
      key: badge.id()
    }, m(BadgeCard, {
      badge: badge,
      username: user.username(),
      timesGranted: count,
      grantedAt: latest.grantedAt()
    }))));
  }
}
flarum.reg.add('ramon-canela', 'forum/features/badges/components/UserBadgesPage', UserBadgesPage);